BEGIN TRANSACTION;
CREATE TABLE aliases (
    demandeur TEXT PRIMARY KEY,
    mapped_nom TEXT NOT NULL
);
CREATE TABLE collaborateurs (
    matricule INTEGER PRIMARY KEY,
    nom TEXT NOT NULL,
    entite TEXT,
    fonction TEXT,
    responsable TEXT
);
CREATE TABLE frais (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    reference TEXT,
    demandeur TEXT,
    societe TEXT,
    mois TEXT,
    semaine TEXT,
    date_creation TEXT,
    etat_demande TEXT,
    url_document TEXT
);
DELETE FROM "sqlite_sequence";
COMMIT;
